import{c as i,Q as n,j as e,m as t}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),r={name:"faq.md"};function s(o,a,u,k,l,h){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Pertanyaan yang sering ditanyakan tentang penggunaan Eznom.</p><hr><h2 id="umum" tabindex="-1">Umum <a class="header-anchor" href="#umum" aria-label="Permalink to &quot;Umum&quot;">​</a></h2><h3 id="apa-itu-eznom" tabindex="-1">Apa itu Eznom? <a class="header-anchor" href="#apa-itu-eznom" aria-label="Permalink to &quot;Apa itu Eznom?&quot;">​</a></h3><p>Eznom adalah platform manajemen ISP berbasis web untuk operator RT/RW Net dan WISP. Eznom membantu mengelola pelanggan PPPoE, hotspot, tagihan bulanan, dan notifikasi otomatis dari satu dasbor.</p><h3 id="apakah-eznom-mendukung-beberapa-router" tabindex="-1">Apakah Eznom mendukung beberapa router? <a class="header-anchor" href="#apakah-eznom-mendukung-beberapa-router" aria-label="Permalink to &quot;Apakah Eznom mendukung beberapa router?&quot;">​</a></h3><p>Ya. Satu akun Eznom bisa mengelola banyak router MikroTik. Setiap router dikelola secara terpisah dengan data pelanggan, tagihan, dan keuangan masing-masing.</p><h3 id="router-mikrotik-versi-berapa-yang-didukung" tabindex="-1">Router MikroTik versi berapa yang didukung? <a class="header-anchor" href="#router-mikrotik-versi-berapa-yang-didukung" aria-label="Permalink to &quot;Router MikroTik versi berapa yang didukung?&quot;">​</a></h3><p>Semua versi RouterOS yang mendukung API (v6 dan v7). Untuk REST API, diperlukan RouterOS 7.1 ke atas.</p><hr><h2 id="router-vpn" tabindex="-1">Router &amp; VPN <a class="header-anchor" href="#router-vpn" aria-label="Permalink to &quot;Router &amp; VPN&quot;">​</a></h2><h3 id="mengapa-router-perlu-terhubung-via-vpn" tabindex="-1">Mengapa router perlu terhubung via VPN? <a class="header-anchor" href="#mengapa-router-perlu-terhubung-via-vpn" aria-label="Permalink to &quot;Mengapa router perlu terhubung via VPN?&quot;">​</a></h3><p>API MikroTik biasanya hanya bisa diakses dari jaringan lokal. VPN memungkinkan server Eznom berkomunikasi dengan router Anda secara aman melalui internet.</p><h3 id="router-saya-status-vpn-terputus-apa-yang-harus-dilakukan" tabindex="-1">Router saya status VPN &quot;Terputus&quot;, apa yang harus dilakukan? <a class="header-anchor" href="#router-saya-status-vpn-terputus-apa-yang-harus-dilakukan" aria-label="Permalink to &quot;Router saya status VPN &quot;Terputus&quot;, apa yang harus dilakukan?&quot;">​</a></h3><ol><li>Pastikan konfigurasi VPN di MikroTik sudah benar sesuai panduan wizard</li><li>Cek apakah port VPN tidak diblokir oleh firewall ISP upstream</li><li>Coba restart interface VPN di MikroTik</li><li>Jika masih gagal, buka tiket ke tim support Eznom</li></ol><h3 id="apakah-sinkronisasi-pppoe-berjalan-otomatis" tabindex="-1">Apakah sinkronisasi PPPoE berjalan otomatis? <a class="header-anchor" href="#apakah-sinkronisasi-pppoe-berjalan-otomatis" aria-label="Permalink to &quot;Apakah sinkronisasi PPPoE berjalan otomatis?&quot;">​</a></h3><p>Ya. Eznom melakukan sinkronisasi status pelanggan (online/offline, IP, uptime) setiap <strong>1 menit</strong> secara otomatis selama VPN router terhubung.</p><hr><h2 id="pelanggan-tagihan" tabindex="-1">Pelanggan &amp; Tagihan <a class="header-anchor" href="#pelanggan-tagihan" aria-label="Permalink to &quot;Pelanggan &amp; Tagihan&quot;">​</a></h2><h3 id="mengapa-pelanggan-baru-saya-belum-punya-tagihan" tabindex="-1">Mengapa pelanggan baru saya belum punya tagihan? <a class="header-anchor" href="#mengapa-pelanggan-baru-saya-belum-punya-tagihan" aria-label="Permalink to &quot;Mengapa pelanggan baru saya belum punya tagihan?&quot;">​</a></h3><p>Tagihan di-generate setiap hari pukul 01:00. Jika pelanggan baru ditambahkan hari ini, tagihannya akan muncul keesokan harinya.</p><h3 id="apakah-tagihan-bisa-di-generate-ulang-jika-ada-kesalahan" tabindex="-1">Apakah tagihan bisa di-generate ulang jika ada kesalahan? <a class="header-anchor" href="#apakah-tagihan-bisa-di-generate-ulang-jika-ada-kesalahan" aria-label="Permalink to &quot;Apakah tagihan bisa di-generate ulang jika ada kesalahan?&quot;">​</a></h3><p>Tidak ada tombol generate ulang karena tagihan menggunakan <code>insertOrIgnore</code> — jika tagihan bulan tersebut sudah ada, tidak akan dibuat duplikat. Untuk mengubah jumlah tagihan, edit langsung di halaman billing pelanggan.</p><h3 id="pelanggan-saya-mengeluh-sudah-bayar-tapi-status-masih-belum-bayar-apa-yang-harus-dilakukan" tabindex="-1">Pelanggan saya mengeluh sudah bayar tapi status masih Belum Bayar. Apa yang harus dilakukan? <a class="header-anchor" href="#pelanggan-saya-mengeluh-sudah-bayar-tapi-status-masih-belum-bayar-apa-yang-harus-dilakukan" aria-label="Permalink to &quot;Pelanggan saya mengeluh sudah bayar tapi status masih Belum Bayar. Apa yang harus dilakukan?&quot;">​</a></h3><p>Jika pembayaran dilakukan di luar sistem (tunai/transfer), gunakan fitur <strong>Catat Pembayaran Manual</strong> di halaman detail tagihan atau detail pelanggan.</p><h3 id="apakah-tagihan-bisa-dikonfigurasi-per-pelanggan" tabindex="-1">Apakah tagihan bisa dikonfigurasi per-pelanggan? <a class="header-anchor" href="#apakah-tagihan-bisa-dikonfigurasi-per-pelanggan" aria-label="Permalink to &quot;Apakah tagihan bisa dikonfigurasi per-pelanggan?&quot;">​</a></h3><p>Ya. Anda bisa mengatur <strong>tanggal jatuh tempo khusus</strong> per-pelanggan yang akan override pengaturan tanggal JT di level router.</p><hr><h2 id="notifikasi" tabindex="-1">Notifikasi <a class="header-anchor" href="#notifikasi" aria-label="Permalink to &quot;Notifikasi&quot;">​</a></h2><h3 id="notifikasi-whatsapp-tidak-terkirim-apa-penyebabnya" tabindex="-1">Notifikasi WhatsApp tidak terkirim, apa penyebabnya? <a class="header-anchor" href="#notifikasi-whatsapp-tidak-terkirim-apa-penyebabnya" aria-label="Permalink to &quot;Notifikasi WhatsApp tidak terkirim, apa penyebabnya?&quot;">​</a></h3><ol><li>Pastikan API Key dan nomor pengirim Fonnte sudah diisi dengan benar</li><li>Cek apakah nomor WA Fonnte Anda masih aktif (tidak terlogout dari perangkat)</li><li>Pastikan nomor pelanggan diisi dengan format yang valid (08xxx atau +62xxx)</li><li>Cek <strong>Tab Notifikasi</strong> di detail pelanggan untuk melihat pesan error</li></ol><h3 id="bisa-ganti-isi-pesan-notifikasi" tabindex="-1">Bisa ganti isi pesan notifikasi? <a class="header-anchor" href="#bisa-ganti-isi-pesan-notifikasi" aria-label="Permalink to &quot;Bisa ganti isi pesan notifikasi?&quot;">​</a></h3><p>Untuk saat ini, template pesan sudah ditentukan oleh sistem dan tidak bisa dikustomisasi bebas. Informasi bisnis Anda (nama, alamat, telepon) akan otomatis disertakan di footer pesan.</p><h3 id="notifikasi-h-7-sudah-dikirim-tapi-tidak-ada-h-3-kenapa" tabindex="-1">Notifikasi H-7 sudah dikirim tapi tidak ada H-3. Kenapa? <a class="header-anchor" href="#notifikasi-h-7-sudah-dikirim-tapi-tidak-ada-h-3-kenapa" aria-label="Permalink to &quot;Notifikasi H-7 sudah dikirim tapi tidak ada H-3. Kenapa?&quot;">​</a></h3><p>Pastikan <strong>H-3 dicentang</strong> di pengaturan notifikasi. Jika baru saja dicentang setelah H-7 sudah terkirim, notifikasi H-3 akan dikirim saat tiba 3 hari sebelum JT.</p><hr><h2 id="kontrak" tabindex="-1">Kontrak <a class="header-anchor" href="#kontrak" aria-label="Permalink to &quot;Kontrak&quot;">​</a></h2><h3 id="link-tanda-tangan-sudah-kedaluwarsa-bagaimana-mengirim-ulang" tabindex="-1">Link tanda tangan sudah kedaluwarsa. Bagaimana mengirim ulang? <a class="header-anchor" href="#link-tanda-tangan-sudah-kedaluwarsa-bagaimana-mengirim-ulang" aria-label="Permalink to &quot;Link tanda tangan sudah kedaluwarsa. Bagaimana mengirim ulang?&quot;">​</a></h3><p>Klik <strong>Kirim Link</strong> di banner kontrak halaman detail pelanggan. Link baru berlaku 7 hari.</p><h3 id="pelanggan-tidak-bisa-membuka-dokumen-kontrak" tabindex="-1">Pelanggan tidak bisa membuka dokumen kontrak. <a class="header-anchor" href="#pelanggan-tidak-bisa-membuka-dokumen-kontrak" aria-label="Permalink to &quot;Pelanggan tidak bisa membuka dokumen kontrak.&quot;">​</a></h3><p>Pastikan pelanggan memasukkan <strong>ID Pelanggan</strong> yang tepat di halaman verifikasi. ID Pelanggan bisa dilihat di halaman detail pelanggan (Tab Kredensial).</p><hr><h2 id="hotspot" tabindex="-1">Hotspot <a class="header-anchor" href="#hotspot" aria-label="Permalink to &quot;Hotspot&quot;">​</a></h2><h3 id="voucher-yang-di-generate-tidak-muncul-di-mikrotik" tabindex="-1">Voucher yang di-generate tidak muncul di MikroTik. <a class="header-anchor" href="#voucher-yang-di-generate-tidak-muncul-di-mikrotik" aria-label="Permalink to &quot;Voucher yang di-generate tidak muncul di MikroTik.&quot;">​</a></h3><p>Pastikan koneksi VPN router aktif (status 🟢 Terhubung) saat generate voucher. Jika VPN terputus, voucher tersimpan di database Eznom tetapi tidak tersync ke MikroTik.</p><h3 id="berapa-maksimum-voucher-yang-bisa-di-generate-sekaligus" tabindex="-1">Berapa maksimum voucher yang bisa di-generate sekaligus? <a class="header-anchor" href="#berapa-maksimum-voucher-yang-bisa-di-generate-sekaligus" aria-label="Permalink to &quot;Berapa maksimum voucher yang bisa di-generate sekaligus?&quot;">​</a></h3><p>500 voucher per sesi generate.</p>',48)])])}const p=i(r,[["render",s]]);export{g as __pageData,p as default};
